<template>
 <div class="held-lab-backdrop" @pointerdown.self="!busy&&$emit('close')" @keydown.stop @keyup.stop>
  <section ref="panel" class="held-lab" role="dialog" aria-modal="true" aria-labelledby="held-lab-title" tabindex="-1" @keydown.esc="!busy&&$emit('close')">
   <header><span><small>SAFARI / LABORATOIRE DE SYNTHÈSE</small><h2 id="held-lab-title">Objets corrompus</h2><p>Un objet familier. Une puissance instable.</p></span><button :disabled="busy" aria-label="Fermer" @click="$emit('close')">×</button></header>
   <div class="held-lab-body">
    <nav aria-label="Recettes"><button v-for="r in panel.recipes" :key="r.key" :aria-pressed="selected===r.key" :disabled="busy||uncertain" @click="select(r.key)"><bag-item-icon :item-key="r.base" pocket="held"/><span>{{ r.name }}<small>{{ quantity(r.base)?'Objet de base disponible':'Objet de base manquant' }}</small></span><b aria-hidden="true">›</b></button></nav>
    <div class="held-lab-recipe" :class="{crafting:busy}">
     <span class="held-lab-result"><bag-item-icon :item-key="recipe.base" pocket="held"/><i>✦</i></span><small class="held-lab-category">ÉQUIPEMENT CORROMPU</small><h3>{{ recipe.name }}</h3><p>{{ recipe.description }}</p>
     <p class="held-lab-restriction">Réservé aux Pokémon corrompus. Les pertes sont calculées sur les PV maximum et peuvent mettre K.O.</p>
     <h4>Composants nécessaires</h4><ul><li v-for="c in recipe.cost" :key="c.key" :class="{missing:quantity(c.key)<c.quantity}"><bag-item-icon :item-key="c.key" :pocket="c.key===recipe.base?'held':'treasures'"/><span>{{ itemName(c.key) }}</span><b>{{ quantity(c.key) }} <small>/ {{ c.quantity }}</small></b></li></ul>
     <p v-if="notice" class="held-lab-notice" role="status">{{ notice }}</p><p v-if="error" class="held-lab-error" role="alert">{{ error }}</p>
     <button class="held-lab-craft" :disabled="busy||(!affordable&&!uncertain)" @click="craft">{{ busy?'Synthèse en cours…':uncertain?'Vérifier la fabrication':affordable?'Fabriquer '+recipe.name:'Composants insuffisants' }}<span aria-hidden="true">✦</span></button><small class="held-lab-cost">1 objet classique + 40 Éclats + 40 Cristaux + 40 Prismes. La fabrication consomme ces composants.</small>
    </div>
   </div>
  </section>
 </div>
</template>
<script>
import BagItemIcon from './BagItemIcon.vue';
import items from '@/data/heldItems.json';
const crystals={crystal_shard:'Éclat fissuré',clear_crystal:'Cristal limpide',aurora_prism:'Prisme d’aurore'};
export default{components:{BagItemIcon},props:{panel:Object,inventory:Array,command:Function},data(){return{selected:this.panel.recipes[0].key,busy:false,uncertain:false,error:'',notice:'',requestId:crypto.randomUUID()};},computed:{recipe(){return this.panel.recipes.find(r=>r.key===this.selected);},affordable(){return this.recipe.cost.every(c=>this.quantity(c.key)>=c.quantity);}},mounted(){this._previous=document.activeElement;this.$refs.panel.focus();},beforeDestroy(){this._previous?.focus?.();},methods:{quantity(key){return Number(this.inventory.find(i=>i.key===key)?.quantity)||0;},itemName(key){return crystals[key]||items[key]?.name||key;},select(key){this.selected=key;this.error='';this.notice='';this.requestId=crypto.randomUUID();},async craft(){if(this.busy||(!this.affordable&&!this.uncertain))return;this.busy=true;this.error='';this.notice='';const began=Date.now();try{const r=await this.command('corruption:heldCraft',{requestId:this.requestId,itemKey:this.selected});await new Promise(resolve=>setTimeout(resolve,Math.max(0,700-(Date.now()-began))));if(!r.success){this.uncertain=!!r.uncertain;this.error=r.message||'Synthèse indisponible.';return;}this.uncertain=false;this.notice=(r.duplicate?'Fabrication déjà sauvegardée : ':'Fabrication réussie : ')+this.recipe.name+' est dans ton sac.';this.requestId=crypto.randomUUID();}catch(e){this.error=e.message;}finally{this.busy=false;}}}};
</script>
