ult .bag-object-icon{width:46px;height:46px}.held-lab-result i{position:absolute;right:5px;bottom:2px;color:#a384bf;font-size:21px;font-style:normal}.held-lab-category{font-size:9px;color:#9675af;letter-spacing:.14em}.held-lab h3{font-size:24px;margin:4px 0 10px;color:var(--journal-heading)}.held-lab-recipe>p{font-size:13px}.held-lab-restriction{padding:10px;border-left:3px solid #a384bf;background:var(--journal-soft);font-size:11px!important}.held-lab h4{font-size:12px;margin:18px 0 8px}.held-lab ul{list-style:none;margin:0;padding:0}.held-lab li{display:flex;align-items:center;gap:10px;padding:9px 0;border-bottom:1px solid var(--journal-border);font-size:12px}.held-lab li>span{flex:1}.held-lab li>b{font-variant-numeric:tabular-nums}.held-lab li small{font-size:10px;color:var(--journal-muted)}.held-lab li.missing>b{color:var(--journal-danger)}.held-lab-craft{display:flex;justify-content:space-between;gap:10px;align-items:center;width:100%;margin-top:20px;padding:12px 16px;background:var(--journal-accent);color:var(--journal-on-accent);font-weight:bold;font-size:12px}.held-lab-cost{display:block;font-size:10px;color:var(--journal-muted);margin-top:8px}.held-lab-notice{color:var(--journal-accent);font-weight:bold}.held-lab-error{color:var(--journal-danger)}.crafting .held-lab-result{animation:held-lab-pulse .6s ease-in-out infinite alternate}@keyframes held-lab-pulse{to{box-shadow:0 0 30px #a878c699;transform:scale(1.07)}}
